    {id:'haul',name:'Haul out the heavy trash',verb:'trash bags hauled',symbol:'🗑️',amount:4,description:'Grab each heavy trash bag on the left, drag it across the floor, and DROP it in the dumpster at the right.',title:'SERVICE HALLWAY · DUMPSTER ON THE RIGHT'},
    {id:'mop',name:'Mop the filthy service floor',verb:'floor patches mopped',symbol:'🧹',amount:6,effort:250,description:'Drag the mop back and forth across every filthy patch. You must actually sweep over each patch multiple times.',title:'CLOSING TIME · FLOOR IS FILTHY'}
