    lastBetSpec={bet,seats,pairs:sideBets.pairs,trio:sideBets.trio};stats.totalWagered+=bet*seats;
    if(shoe.length<cutRemaining+14){shoe=makeShoe();$('shoeDecoration').classList.remove('shoe-shuffle');void $('shoeDecoration').offsetWidth;$('shoeDecoration').classList.add('shoe-shuffle');}
    dealer=[];hands=Array.from({length:seats},(_,i)=>newHand(bet,i+1));activeHand=0;betHistory=[];
    sound('ui_confirm');setMessage('Dealer is dealing from the six-deck shoe…');showError('');view();
    if(window.innerWidth<=750)window.scrollTo({top:0,behavior:preferReducedMotion?'instant':'smooth'});
    for(const h of hands){await delay(115);h.cards.push(drawForTable());sound('card_slide');view();}
    await delay(120);dealer.push(drawForTable());sound('card_slide');view();
    for(const h of hands){await delay(115);h.cards.push(drawForTable());sound('card_slide');view();}
