      if(insuranceAmount){balance+=insuranceAmount*3;sideResults.push(`Insurance paid +◈${fmt(insuranceAmount*2)}`);}
      setMessage('Dealer has Blackjack.');sound('card_flip');view();await delay(260);settle();return;
