    balance=money(balance-h.wager);stats.totalWagered+=h.wager;h.wager=money(h.wager*2);h.doubled=true;phase='dealing';sound('chip_allin');setMessage('Double down · one final card.');view();await delay(180);
    h.cards.push(drawForTable());sound('card_slide');celebrateTwentyOne(h);h.complete=true;view();await delay(190);await advance();
